"""One-shot setup against LocalStack: tables, stream, bucket, topic, DLQ, Lambda + trigger, seed cards.
Idempotent: safe to re-run. A re-run only adds MISSING cards, so card history and blocks are kept.
Set RESEED=1 to reset every card (wipes history and unblocks blocked cards)."""
import io, json, os, sys, time, zipfile
from decimal import Decimal

from botocore.exceptions import ClientError

from common.aws import client, resource

STREAM, FN, TABLE = "payment-events", "feature-updater", "card_features"
FEATURE_MODE = os.environ.get("FEATURE_MODE", "lambda")      # lambda | poller
LAMBDA_ENDPOINT = os.environ.get("LAMBDA_AWS_ENDPOINT", "http://localstack:4566")
CARDS_FILE = os.environ.get("CARDS_FILE", "/data/cards.jsonl")
RESEED = os.environ.get("RESEED") == "1"     # CHANGED (A5): opt-in full reset of every card
DLQ_NAME = "feature-updater-dlq"             # CHANGED (A4)
# CHANGED (A4): bad data is skipped inside the handler, so anything that still fails is infrastructure
# (e.g. DynamoDB down). Be patient with that, but never block the shard forever.
FAILURE_SETTINGS = {"BisectBatchOnFunctionError": True, "MaximumRetryAttempts": 10,
                    "MaximumRecordAgeInSeconds": 3600}


def wait_for_localstack():
    import urllib.request
    url = os.environ["AWS_ENDPOINT_URL"] + "/_localstack/health"
    for _ in range(90):
        try:
            h = json.load(urllib.request.urlopen(url, timeout=2))["services"]
            if all(h.get(s) in ("available", "running") for s in ("dynamodb", "kinesis", "s3", "sns")):
                return
        except Exception:
            pass
        time.sleep(1)
    sys.exit("LocalStack did not become healthy")


def ensure_table(ddb, name, key, ttl_attr=None, pitr=False):
    try:
        ddb.create_table(TableName=name, BillingMode="PAY_PER_REQUEST",
                         AttributeDefinitions=[{"AttributeName": key, "AttributeType": "S"}],
                         KeySchema=[{"AttributeName": key, "KeyType": "HASH"}])
        ddb.get_waiter("table_exists").wait(TableName=name)
        print(f"created table {name}")
    except ddb.exceptions.ResourceInUseException:
        print(f"table {name} exists")
    for fn in (
        (lambda: ddb.update_time_to_live(TableName=name, TimeToLiveSpecification={
            "Enabled": True, "AttributeName": ttl_attr})) if ttl_attr else None,
        (lambda: ddb.update_continuous_backups(TableName=name, PointInTimeRecoverySpecification={
            "PointInTimeRecoveryEnabled": True})) if pitr else None,
    ):
        if fn:
            try:
                fn()
            except Exception as e:                      # nice-to-have locally
                print(f"  (skipped TTL/PITR on {name}: {e})")


def ensure_stream(kin):
    try:
        kin.create_stream(StreamName=STREAM, ShardCount=2)   # on AWS: StreamModeDetails ON_DEMAND
        print("created stream")
    except kin.exceptions.ResourceInUseException:
        print("stream exists")
    for _ in range(60):
        d = kin.describe_stream(StreamName=STREAM)["StreamDescription"]
        if d["StreamStatus"] == "ACTIVE":
            return d["StreamARN"]
        time.sleep(1)
    sys.exit("stream never became ACTIVE")


def _wait_lambda(lam):
    """CHANGED (A6): Lambda rejects a second update while one is in progress, so wait between steps."""
    for _ in range(180):                                  # first run pulls the Lambda runtime image
        st = lam.get_function(FunctionName=FN)["Configuration"]
        if st.get("State") == "Failed" or st.get("LastUpdateStatus") == "Failed":
            raise RuntimeError(st.get("StateReason") or st.get("LastUpdateStatusReason"))
        if st.get("State") == "Active" and st.get("LastUpdateStatus", "Successful") == "Successful":
            return
        time.sleep(1)
    raise RuntimeError("Lambda did not become Active within 180 s")


def _ensure_dlq():
    """CHANGED (A4): SQS queue for batches that still fail after every retry. Returns its ARN, or None."""
    try:
        sqs = client("sqs")
        url = sqs.create_queue(QueueName=DLQ_NAME)["QueueUrl"]          # safe to call again
        return sqs.get_queue_attributes(QueueUrl=url, AttributeNames=["QueueArn"])["Attributes"]["QueueArn"]
    except Exception as e:                                             # e.g. SQS not enabled in LocalStack
        print(f"  (no DLQ: {e})")
        return None


def _ensure_mapping(lam, stream_arn):
    """CHANGED (A4): Kinesis trigger with retry limits + DLQ. Falls back to defaults if LocalStack refuses."""
    failure = dict(FAILURE_SETTINGS)
    dlq = _ensure_dlq()
    if dlq:
        failure["DestinationConfig"] = {"OnFailure": {"Destination": dlq}}
    base = dict(EventSourceArn=stream_arn, FunctionName=FN, StartingPosition="TRIM_HORIZON",
                BatchSize=100, MaximumBatchingWindowInSeconds=1)
    maps = lam.list_event_source_mappings(FunctionName=FN)["EventSourceMappings"]
    try:
        if maps:
            lam.update_event_source_mapping(UUID=maps[0]["UUID"], **failure)   # fixes an old mapping too
        else:
            lam.create_event_source_mapping(**base, **failure)
        return dlq
    except Exception as e:
        print(f"  (failure settings not supported here: {e}; using default retry behaviour)")
        if not maps:
            lam.create_event_source_mapping(**base)
        return None


def ensure_lambda(lam, stream_arn):
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:         # flat layout: handler.py + core.py
        z.write("feature_updater/handler.py", "handler.py")
        z.write("feature_updater/core.py", "core.py")
    code = buf.getvalue()
    env = {"Variables": {"TABLE_NAME": TABLE, "DDB_ENDPOINT": LAMBDA_ENDPOINT}}
    try:
        lam.get_function(FunctionName=FN)
        exists = True
    except lam.exceptions.ResourceNotFoundException:
        exists = False
    if exists:
        lam.update_function_code(FunctionName=FN, ZipFile=code)
        _wait_lambda(lam)                                                    # CHANGED (A6): one update at a time
        lam.update_function_configuration(FunctionName=FN, Environment=env)   # CHANGED (A6): env was never updated
    else:
        lam.create_function(FunctionName=FN, Runtime="python3.12",
                            Role="arn:aws:iam::000000000000:role/lambda-role", Handler="handler.lambda_handler",
                            Code={"ZipFile": code}, Timeout=30, MemorySize=256, Environment=env)
    _wait_lambda(lam)
    dlq = _ensure_mapping(lam, stream_arn)                                   # CHANGED (A4)
    print("lambda + Kinesis trigger ready" + (f" (DLQ: {DLQ_NAME})" if dlq else " (no DLQ)"))


def _existing_tokens(table):
    """CHANGED (A5): card_tokens already in the table, so a re-run never overwrites them."""
    kw, out = {"ProjectionExpression": "card_token"}, set()
    while True:                                                              # pages: one scan returns max 1 MB
        r = table.scan(**kw)
        out.update(i["card_token"] for i in r["Items"])
        if "LastEvaluatedKey" not in r:
            return out
        kw["ExclusiveStartKey"] = r["LastEvaluatedKey"]


def seed(ddb_res):
    if not os.path.exists(CARDS_FILE):                                       # CHANGED (A5): dead code removed
        sys.exit(f"!! {CARDS_FILE} not found. Run the generator first so data/cards.jsonl exists, "
                 "then: docker compose up -d")
    table = ddb_res.Table(TABLE)
    have = set() if RESEED else _existing_tokens(table)                     # CHANGED (A5)
    now, added, kept = time.time(), 0, 0
    with table.batch_writer() as bw, open(CARDS_FILE) as fh:
        for line in fh:
            c = json.loads(line)
            if c["token"] in have:                                           # CHANGED (A5): keep history + blocks
                kept += 1
                continue
            bw.put_item(Item={"card_token": c["token"], "txn_count_5m": 0, "blocked": False,
                              "avg_amount_30d": Decimal(c["avg"]), "avg_n": 20,
                              "known_devices": set(c["devices"]), "recent": "[]",
                              "updated_at": Decimal(str(round(now, 3))), "expires_at": int(now + 30 * 86400)})
            added += 1
    print(f"seeded {added} new cards, kept {kept} existing" + (" (RESEED=1: full reset)" if RESEED else ""))


def main():
    wait_for_localstack()
    ddb, ddb_res, kin = client("dynamodb"), resource("dynamodb"), client("kinesis")
    ensure_table(ddb, TABLE, "card_token", ttl_attr="expires_at", pitr=True)
    ensure_table(ddb, "cases", "case_id")
    ensure_table(ddb, "alerts", "event_id")
    ensure_table(ddb, "consumer_checkpoints", "consumer_id")
    arn = ensure_stream(kin)
    s3 = client("s3")
    try:
        s3.create_bucket(Bucket="fraud-labels")
    except ClientError as e:
        if e.response["Error"]["Code"] not in ("BucketAlreadyOwnedByYou", "BucketAlreadyExists"):
            raise
    client("sns").create_topic(Name="fraud-alerts")
    if FEATURE_MODE == "lambda":
        try:
            ensure_lambda(client("lambda"), arn)
        except Exception as e:
            print(f"!! Lambda setup failed: {e}\n!! Use the poller instead: see README 'If the Lambda trigger fails'.")
    else:
        print("FEATURE_MODE=poller: skipping Lambda; run the poller service")
    seed(ddb_res)
    print("SETUP DONE")


if __name__ == "__main__":
    main()
